<?php
require __DIR__.'/../includes/study-engine/engine.php';
require_once __DIR__.'/../includes/study-engine/persistence/NotificationIntentRepository.php';
use EIPSI\StudyEngine\Engine as E;
$tests=0;$failures=0;
function lc_assert($v,$m='Assertion failed'){if(!$v)throw new RuntimeException($m);}
function lc_test($name,$f){global $tests,$failures;$tests++;try{$f();echo "PASS $name\n";}catch(Throwable $e){$failures++;echo "FAIL $name: ".$e->getMessage()."\n";}}
function lc_fixture($prefix='01'){$p=glob(__DIR__.'/study-engine/fixtures/valid/'.$prefix.'*.json');$d=json_decode(file_get_contents($p[0]),true);foreach($d['nodes'] as &$n)if(($n['completion_boundary']??null)==='ASSESSMENT')$n['metadata']['native_questions']=array(array('id'=>'NQ_ONE','label'=>'Primera','response_key'=>'NR_ONE','value_type'=>'NUMBER','options'=>array(),'page'=>0,'randomization_id'=>null),array('id'=>'NQ_TWO','label'=>'Segunda','response_key'=>'NR_TWO','value_type'=>'STRING','options'=>array(),'page'=>0,'randomization_id'=>null),array('id'=>'NQ_THREE','label'=>'Tercera','response_key'=>'NR_THREE','value_type'=>'SET','options'=>array(),'page'=>1,'randomization_id'=>null));unset($n);return $d;}
function lc_rule($source='E_SIMPLE',$actions=null){return array('id'=>'LC_ONE','label'=>'Ruta de prueba','source'=>array('assessment_id'=>$source,'question_id'=>'NQ_ONE'),'event'=>'ANSWER','priority'=>1,'predicate'=>array('op'=>'GTE','reference'=>array('kind'=>'ANSWER','assessment_id'=>$source,'question_id'=>'NQ_ONE'),'value'=>3),'actions'=>$actions??array(array('type'=>'END_ASSESSMENT')));}
function lc_reject($fn,$code){try{$fn();}catch(Throwable $e){lc_assert(strpos($e->getMessage(),$code)!==false,$e->getMessage());return;}throw new RuntimeException('Expected '.$code);}
function lc_sim($d){return new E\Simulator((new E\DefinitionCompiler())->compile($d),array('created_at'=>'2026-10-12T11:00:00Z','timezone'=>'UTC','seed_hex'=>str_repeat('01',32)));}
lc_test('Nested expressions preserve unknown through NOT and membership supports sets',function(){$p=array('op'=>'OR','args'=>array(array('op'=>'AND','args'=>array(array('op'=>'GTE','reference'=>array('id'=>'a'),'value'=>3),array('op'=>'IN','reference'=>array('id'=>'b'),'value'=>array('A','C')))),array('op'=>'NOT','arg'=>array('op'=>'EQ','reference'=>array('id'=>'c'),'value'=>true))));$lookup=static function($r){return array('known'=>$r['id']!=='c','value'=>$r['id']==='a'?4:array('B','C'));};lc_assert(E\LogicalConditions::evaluate($p,$lookup)==='TRUE');lc_assert(E\LogicalConditions::evaluate(array('op'=>'NOT','arg'=>array('op'=>'EQ','reference'=>array(),'value'=>true)),static function(){return array('known'=>false,'value'=>null);})==='UNKNOWN');});
lc_test('Explicit ordinal resolves incompatible flow but keeps compatible structural actions',function(){$a=lc_rule();$a['actions']=array(array('type'=>'JUMP','target_id'=>'A'));$b=$a;$b['id']='LC_TWO';$b['priority']=2;$b['actions']=array(array('type'=>'CANCEL_BLOCK','target_id'=>'C'),array('type'=>'JUMP','target_id'=>'B'));$r=E\LogicalConditions::resolve(array($b,$a),static function(){return array('known'=>true,'value'=>4);});lc_assert(count($r['actions'])===2&&$r['actions'][0]['action']['target_id']==='A'&&$r['actions'][1]['action']['target_id']==='C');lc_assert(count($r['audit'][1]['suppressed'])===1);});
lc_test('Compiler validates Native question identity and comparator types',function(){$d=lc_fixture();$r=lc_rule();$r['predicate']['reference']['question_id']='NQ_TWO';$d['protocol_metadata']['trajectory_conditions']=array($r);lc_reject(function()use($d){(new E\DefinitionCompiler())->compile($d);},'INCOMPATIBLE_LOGICAL_COMPARATOR');$d['protocol_metadata']['trajectory_conditions'][0]['predicate']['reference']['question_id']='NQ_MISSING';lc_reject(function()use($d){(new E\DefinitionCompiler())->compile($d);},'INVALID_LOGICAL_QUESTION_REFERENCE');});
lc_test('Backward intra-Assessment navigation cannot publish',function(){$d=lc_fixture();$r=lc_rule();$r['source']['question_id']='NQ_TWO';$r['actions']=array(array('type'=>'GO_QUESTION','target_id'=>'E_SIMPLE','question_id'=>'NQ_ONE'));$d['protocol_metadata']['trajectory_conditions']=array($r);lc_reject(function()use($d){(new E\DefinitionCompiler())->compile($d);},'BACKWARD_QUESTION_JUMP');});
lc_test('Logical action failures rollback answers audit and every preceding action',function(){$d=lc_fixture();$r=lc_rule();$r['actions']=array(array('type'=>'END_ASSESSMENT'),array('type'=>'JUMP','target_id'=>'E_SIMPLE'));$d['protocol_metadata']['trajectory_conditions']=array($r);$s=lc_sim($d);$before=$s->snapshot();$id=array_values(array_filter($before['instances'],static function($i){return $i['definition_id']==='E_SIMPLE';}))[0]['id'];lc_reject(function()use($s,$id){$s->dispatch(array('id'=>'LOGIC_FAIL','kind'=>'NATIVE_LOGIC','data'=>array('block_execution_id'=>$id,'answers'=>array('NQ_ONE'=>4),'question_states'=>array('NQ_ONE'=>'answered'),'changed_questions'=>array('NQ_ONE'))));},'LOGICAL_TARGET_UNAVAILABLE');lc_assert($before===$s->snapshot());});
lc_test('Question jump records explicit skipped states and roundtrips without reapplying',function(){$d=lc_fixture();$d['protocol_metadata']['trajectory_conditions']=array(lc_rule('E_SIMPLE',array(array('type'=>'GO_QUESTION','target_id'=>'E_SIMPLE','question_id'=>'NQ_THREE'))));$s=lc_sim($d);$id=$s->nextAction()['payload']['assessment_execution_id'];$command=array('id'=>'LOGIC_GO','kind'=>'NATIVE_LOGIC','data'=>array('block_execution_id'=>$id,'answers'=>array('NQ_ONE'=>4),'question_states'=>array('NQ_ONE'=>'answered','NQ_TWO'=>'unanswered'),'changed_questions'=>array('NQ_ONE')));$s->dispatch($command);$snapshot=$s->snapshot();lc_assert($snapshot['logical_trajectory']['question_states']['E_SIMPLE']['NQ_TWO']==='skipped_by_logic');$copy=E\Simulator::restore($s->compiled(),$s->checkpoint(),str_repeat('01',32));lc_assert($copy->snapshot()===$snapshot);$copy->dispatch(array_replace($command,array('id'=>'LOGIC_REDELIVERY')));lc_assert(count($copy->snapshot()['logical_trajectory']['audit'])===1);});
lc_test('Future randomization remains unresolved before its traversal point',function(){$d=lc_fixture('06');$d['protocol_metadata']['trajectory_conditions']=array(lc_rule('E_SCREEN',array(array('type'=>'FORCE_RANDOM','target_id'=>'M_ARM','candidate_ids'=>array('M_ARM_B')))));$s=lc_sim($d);lc_assert(!$s->snapshot()['random_decisions']);$id=$s->nextAction()['payload']['assessment_execution_id'];$s->dispatch(array('id'=>'FORCE_ARM','kind'=>'NATIVE_LOGIC','data'=>array('block_execution_id'=>$id,'answers'=>array('NQ_ONE'=>4),'question_states'=>array('NQ_ONE'=>'answered'),'changed_questions'=>array('NQ_ONE'))));lc_assert(!$s->snapshot()['random_decisions']);lc_assert($s->snapshot()['logical_trajectory']['random_controls']['M_ARM']['forced']===array('M_ARM_B'));});
