    $d=lc_fixture('03');foreach($d['nodes'] as &$n)if($n['id']==='M_ROOT')$n['metadata']['role']='LONGITUDINAL_BLOCK';unset($n);$d['protocol_metadata']['trajectory_conditions']=array(lc_rule('E_PRE',array(array('type'=>'CANCEL_BLOCK','target_id'=>'M_ROOT'))));$s=lc_sim($d);$id=$s->nextAction()['payload']['assessment_execution_id'];$s->dispatch(array('id'=>'START_NATIVE','kind'=>'OPEN_ASSESSMENT','data'=>array('block_execution_id'=>$id)));$s->dispatch(array('id'=>'CANCEL_FUTURE','kind'=>'NATIVE_LOGIC','data'=>array('block_execution_id'=>$id,'answers'=>array('NQ_ONE'=>4),'question_states'=>array('NQ_ONE'=>'answered'),'changed_questions'=>array('NQ_ONE'))));lc_assert($s->snapshot()['instances'][$id]['state']==='IN_PROGRESS');lc_assert(\EIPSI\StudyEngine\Persistence\NotificationIntentRepository::logicalCancellation($s->snapshot(),$s->snapshot()['instances'][$id]),'Cancelled block must suppress reminders even for its preserved current Assessment');foreach($s->snapshot()['instances'] as $i)if($i['definition_id']==='E_POST')lc_assert($i['state']==='NOT_SCHEDULED');lc_assert(E\Simulator::restore($s->compiled(),$s->checkpoint(),str_repeat('01',32))->snapshot()===$s->snapshot());
});
