    $s->dispatch(array('id'=>'NATIVE_RESOLVED','kind'=>'NATIVE_LOGIC','data'=>array('block_execution_id'=>$id,'transition_id'=>'CMD_NATIVE|ANSWER','native_randomizations'=>array('E_SIMPLE'=>array('blocks'=>array('RN_LAZY'=>array('order'=>array('RC_B'))))))));$snap=$s->snapshot();lc_assert($snap['logical_trajectory']['navigation']['question_id']==='NQ_THREE');lc_assert($snap['logical_trajectory']['navigation']['transition_id']==='CMD_NATIVE|ANSWER');$count=count($snap['logical_trajectory']['audit']);$s->dispatch(array('id'=>'NATIVE_CLOCK','kind'=>'ADVANCE_TIME','data'=>array('at'=>'2026-10-12T11:01:00Z')));lc_assert(count($s->snapshot()['logical_trajectory']['audit'])===$count);
