    $d=lc_fixture('06');foreach($d['nodes'] as &$n)if($n['id']==='M_ARM'){$n['randomization']['weights']['M_ARM_A']=0;}unset($n);$a=lc_rule('E_INTERVENTION_A');$b=lc_rule('E_SCREEN');$b['id']='LC_CONTRADICTION';$b['predicate']=array('op'=>'AND','args'=>array($b['predicate'],array('op'=>'NOT','arg'=>$b['predicate'])));$d['protocol_metadata']['trajectory_conditions']=array($a,$b);$issues=E\LogicalConditions::diagnostics($d);$codes=array_column($issues,'code');lc_assert(in_array('UNREACHABLE_ASSESSMENT_ZERO_WEIGHT',$codes,true));lc_assert(in_array('UNREACHABLE_QUESTION_ZERO_WEIGHT',$codes,true));lc_assert(in_array('DEAD_CONDITION_UNREACHABLE_SOURCE',$codes,true));lc_assert(in_array('DEAD_CONDITION_CONTRADICTORY_PREDICATE',$codes,true));foreach($issues as $issue)lc_assert($issue['severity']==='WARNING');
