function lc_planned($prefix='06'){$d=lc_fixture($prefix);$d['protocol_metadata']['execution_planning']='DEPENDENCY_PLAN_V1';return $d;}
function lc_logic($s,$source,$value,$id,$event='ANSWER'){$s->dispatch(array('id'=>$id,'kind'=>'NATIVE_LOGIC','data'=>array('block_execution_id'=>$s->instance($source)['id'],'answers'=>array('NQ_ONE'=>$value),'question_states'=>array('NQ_ONE'=>'answered'),'changed_questions'=>array('NQ_ONE'),'event'=>$event)));}
lc_test('Dependency plan resolves independent future randomizations before their schedule',function(){$d=lc_planned();$s=lc_sim($d);lc_assert(count($s->snapshot()['random_decisions'])===1);lc_assert($s->instance('M_ARM')['state']==='BLOCKED');$decision=array_values($s->snapshot()['random_decisions'])[0];lc_assert($decision['decided_at']==='2026-10-12T11:00:00Z');lc_assert($s->snapshot()['dependency_plan']['contract']==='DEPENDENCY_PLAN_V1');$copy=E\Simulator::restore($s->compiled(),$s->checkpoint(),str_repeat('01',32));lc_assert($copy->snapshot()===$s->snapshot());$copy->dispatch(array('id'=>'PLAN_REFRESH','kind'=>'RELOAD'));lc_assert($copy->snapshot()['random_decisions']===$s->snapshot()['random_decisions']);});
lc_test('External randomization waits for final completion even after a provisional matching answer',function(){$d=lc_planned();$d['protocol_metadata']['trajectory_conditions']=array(lc_rule('E_SCREEN',array(array('type'=>'FORCE_RANDOM','target_id'=>'M_ARM','candidate_ids'=>array('M_ARM_B')))));$s=lc_sim($d);lc_assert(!$s->snapshot()['random_decisions']);lc_assert($s->snapshot()['dependency_plan']['randomizations'][$s->instance('M_ARM')['id']]['status']==='PENDING_CONDITION');lc_logic($s,'E_SCREEN',4,'PLAN_FORCE');lc_assert(!$s->snapshot()['random_decisions']);lc_logic($s,'E_SCREEN',4,'PLAN_FORCE_COMPLETE','COMPLETE');$draw=array_values($s->snapshot()['random_decisions']);lc_assert(count($draw)===1&&$draw[0]['selection']===array('M_ARM_B'));lc_assert($s->instance('M_ARM')['state']==='BLOCKED');});
