lc_test('Explicit state trigger fires only on the selected element and destination state',function(){$d=lc_planned('03');$r=lc_rule('E_PRE',array(array('type'=>'CANCEL_BLOCK','target_id'=>'E_POST')));$r['event']='BLOCK_STATE';unset($r['source']['question_id']);$r['trigger']=array('node_id'=>'E_PRE','state'=>'IN_PROGRESS');$r['predicate']=array('op'=>'EQ','reference'=>array('kind'=>'BLOCK_STATE','node_id'=>'E_PRE'),'value'=>'IN_PROGRESS');$d['protocol_metadata']['trajectory_conditions']=array($r);$s=lc_sim($d);lc_assert(!$s->snapshot()['logical_trajectory']['audit']);$s->dispatch(array('id'=>'STATE_OPEN','kind'=>'OPEN_ASSESSMENT','data'=>array('node_id'=>'E_PRE')));lc_assert($s->instance('E_POST')['state']==='NOT_SCHEDULED');lc_assert($s->instance('E_PRE')['state']==='IN_PROGRESS');$audit=$s->snapshot()['logical_trajectory']['audit'];lc_assert(count($audit)===1);$copy=E\Simulator::restore($s->compiled(),$s->checkpoint(),str_repeat('01',32));$copy->dispatch(array('id'=>'STATE_RELOAD','kind'=>'RELOAD'));lc_assert($copy->snapshot()['logical_trajectory']['audit']===$audit);});
