lc_test('Independent Native decisions are planned before their page and consumed unchanged',function(){require_once __DIR__.'/../includes/assessment-editor/Definition.php';require_once __DIR__.'/../includes/assessment-editor/Randomization.php';$native=json_decode(file_get_contents(__DIR__.'/assessment-editor/randomization-fixture.json'),true);$e=$native['elements'][0];$r=array('id'=>$e['id'],'candidates'=>array_column($e['children'],'id'),'weights'=>array_fill_keys(array_column($e['children'],'id'),1),'mode'=>$e['properties']['mode'],'count'=>$e['properties']['count'],'algorithm'=>$e['properties']['algorithm']??'legacy','order'=>$e['properties']['order'],'always_show'=>array(),'fixed'=>array(),'page'=>1);$d=lc_planned('01');foreach($d['nodes'] as &$n)if($n['id']==='E_SIMPLE')$n['metadata']['native_randomizations']=array($r);unset($n);$s=lc_sim($d);$plans=$s->snapshot()['logical_trajectory']['native_plans'][$s->instance('E_SIMPLE')['id']];lc_assert(isset($plans[$r['id']]));$record=\EIPSI\AssessmentEditor\Randomization::reach($native,\EIPSI\AssessmentEditor\Randomization::lazy(1),0,999,array(),0,$plans);lc_assert($record['blocks'][$r['id']]===$plans[$r['id']]);$copy=E\Simulator::restore($s->compiled(),$s->checkpoint(),str_repeat('01',32));lc_assert($copy->snapshot()===$s->snapshot());});
