lc_test('Responsive Native selection returns to its initial result with the same persisted seed',function(){$d=lc_planned('01');$random=array('id'=>'NR_RESPONSIVE','candidates'=>array('CA','CB'),'weights'=>array('CA'=>1,'CB'=>1),'mode'=>'select','count'=>1,'algorithm'=>'weighted_positions','always_show'=>array(),'fixed'=>array(),'page'=>1);foreach($d['nodes'] as &$n)if($n['id']==='E_SIMPLE')$n['metadata']['native_randomizations']=array($random);unset($n);$d['protocol_metadata']['trajectory_conditions']=array(lc_rule('E_SIMPLE',array(array('type'=>'FORCE_RANDOM','target_id'=>'E_SIMPLE','randomization_id'=>'NR_RESPONSIVE','candidate_ids'=>array('CB')))));$s=lc_sim($d);$id=$s->instance('E_SIMPLE')['id'];$initial=$s->snapshot()['logical_trajectory']['native_plans'][$id]['NR_RESPONSIVE']['order'];$seed=$s->checkpoint()['context']['native_plan_seeds'][$id.'|NR_RESPONSIVE'];lc_logic($s,'E_SIMPLE',4,'RESP_TRUE');lc_assert($s->snapshot()['logical_trajectory']['native_plans'][$id]['NR_RESPONSIVE']['order']===array('CB'));lc_logic($s,'E_SIMPLE',1,'RESP_FALSE');lc_assert($s->snapshot()['logical_trajectory']['native_plans'][$id]['NR_RESPONSIVE']['order']===$initial);lc_assert($s->checkpoint()['context']['native_plan_seeds'][$id.'|NR_RESPONSIVE']===$seed);$copy=E\Simulator::restore($s->compiled(),$s->checkpoint(),str_repeat('01',32));lc_assert($copy->snapshot()===$s->snapshot());lc_logic($copy,'E_SIMPLE',4,'RESP_RESTORED');lc_assert($copy->snapshot()['logical_trajectory']['native_plans'][$id]['NR_RESPONSIVE']['order']===array('CB'));});
lc_test('External final answer replaces a provisional match before selecting the branch',function(){$d=lc_planned();$d['protocol_metadata']['trajectory_conditions']=array(lc_rule('E_SCREEN',array(array('type'=>'FORCE_RANDOM','target_id'=>'M_ARM','candidate_ids'=>array('M_ARM_B')))));$s=lc_sim($d);lc_logic($s,'E_SCREEN',4,'EXT_PROVISIONAL');lc_assert(!$s->snapshot()['random_decisions']);lc_logic($s,'E_SCREEN',1,'EXT_FINAL','COMPLETE');lc_assert(count($s->snapshot()['random_decisions'])===1);lc_assert(empty($s->snapshot()['logical_trajectory']['random_controls']['M_ARM']));});
lc_test('Cancelling a repeated assessment affects only the source opportunity and survives recovery',function(){
    $d=lc_planned('04');$d['protocol_metadata']['trajectory_conditions']=array(lc_rule('E_DIARY',array(array('type'=>'CANCEL_BLOCK','target_id'=>'E_DIARY'))));$s=lc_sim($d);$before=$s->snapshot()['instances'];$opportunities=array_values(array_filter($before,static function($i){return $i['definition_id']==='E_DIARY';}));lc_assert(count($opportunities)===7);$first=$opportunities[0];
    $s->dispatch(array('id'=>'CANCEL_ONE_DAY','kind'=>'NATIVE_LOGIC','data'=>array('block_execution_id'=>$first['id'],'answers'=>array('NQ_ONE'=>4),'question_states'=>array('NQ_ONE'=>'answered'),'changed_questions'=>array('NQ_ONE'))));
    lc_assert($s->snapshot()['instances'][$first['id']]['state']==='NOT_SCHEDULED');foreach(array_slice($opportunities,1) as $i)lc_assert($s->snapshot()['instances'][$i['id']]['state']===$before[$i['id']]['state']);
    $copy=E\Simulator::restore($s->compiled(),$s->checkpoint(),str_repeat('01',32));$copy->dispatch(array('id'=>'CANCEL_ONE_RELOAD','kind'=>'RELOAD'));foreach(array_slice($opportunities,1) as $i)lc_assert($copy->snapshot()['instances'][$i['id']]['state']!== 'NOT_SCHEDULED');lc_assert(count($copy->snapshot()['logical_trajectory']['cancelled_opportunities'])===1);
});
