    $d=lc_planned('01');$d['protocol_metadata']['trajectory_conditions']=array(lc_rule('E_SIMPLE',array(array('type'=>'CANCEL_BLOCK','target_id'=>'E_SIMPLE'))));$s=lc_sim($d);$s->dispatch(array('id'=>'OPEN_PROTECTED','kind'=>'OPEN_ASSESSMENT','data'=>array('node_id'=>'E_SIMPLE')));lc_logic($s,'E_SIMPLE',4,'CANCEL_PROTECTED');lc_assert($s->instance('E_SIMPLE')['state']==='IN_PROGRESS');lc_assert($s->snapshot()['logical_trajectory']['answers']['E_SIMPLE']['NQ_ONE']===4);
