function lc_past_definition(){
    $d=lc_fixture();$base=array_values(array_filter($d['nodes'],static function($n){return ($n['completion_boundary']??null)==='ASSESSMENT';}))[0];
    $d['nodes']=array_values(array_filter($d['nodes'],static function($n)use($d){return in_array($n['id'],$d['root_block_ids'],true);}));
    foreach(array('PAST','CURRENT','FUTURE') as $i=>$id){$n=$base;$n['id']=$id;$n['position']=$i;$d['nodes'][]=$n;}return $d;
}
lc_test('Track past respects selected random order and excludes mutually exclusive branches',function(){
    $d=lc_past_definition();$root=$d['root_block_ids'][0];$d['nodes'][0]['randomization']=array('candidates'=>array('PAST','CURRENT','FUTURE'));$rule=array('source'=>array('assessment_id'=>'CURRENT'),'event'=>'COMPLETE');$ref=array('kind'=>'ANSWER','assessment_id'=>'PAST','question_id'=>'NQ_ONE');
    lc_assert(E\LogicalPast::allows($d,$rule,$ref,array($root=>array('PAST','CURRENT','FUTURE')),array()));
    lc_assert(!E\LogicalPast::allows($d,$rule,$ref,array($root=>array('CURRENT','PAST','FUTURE')),array()));
    lc_assert(!E\LogicalPast::allows($d,$rule,$ref,array($root=>array('CURRENT')),array()));
    lc_assert(E\LogicalPast::allows($d,$rule,array('kind'=>'BLOCK_STATE','node_id'=>$root),array($root=>array('CURRENT')),array()));
});
lc_test('Track past follows scheduled time and same-assessment question boundaries',function(){
    $d=lc_past_definition();$d['nodes'][1]['schedule']['temporal_rule']=array('kind'=>'LOCAL_DAY_TIME','day_index'=>3,'time'=>'08:00');$d['nodes'][2]['schedule']['temporal_rule']=array('kind'=>'LOCAL_DAY_TIME','day_index'=>2,'time'=>'08:00');
    $r=array('source'=>array('assessment_id'=>'CURRENT','question_id'=>'NQ_ONE'),'event'=>'ANSWER');
    lc_assert(!E\LogicalPast::allows($d,$r,array('kind'=>'BLOCK_STATE','node_id'=>'PAST'),array(),array()));
    lc_assert(E\LogicalPast::allows($d,$r,array('kind'=>'BLOCK_STATE','node_id'=>'FUTURE'),array(),array()));
    $q=array('kind'=>'ANSWER','assessment_id'=>'CURRENT','question_id'=>'NQ_TWO');lc_assert(!E\LogicalPast::allows($d,$r,$q,array(),array()));$r['event']='COMPLETE';lc_assert(E\LogicalPast::allows($d,$r,$q,array(),array()));
});
lc_test('Runtime future references remain unknown under NOT and survive recovery while old rules retain behavior',function(){
    foreach(array(true,false) as $scoped){$d=lc_fixture();$r=lc_rule();$r['predicate']=array('op'=>'NOT','arg'=>array('op'=>'EQ','reference'=>array('kind'=>'ANSWER','assessment_id'=>'E_SIMPLE','question_id'=>'NQ_TWO'),'value'=>'stop'));if($scoped)$r['reference_scope']='TRACK_PAST_V1';$d['protocol_metadata']['trajectory_conditions']=array($r);$s=lc_sim($d);$id=$s->nextAction()['payload']['assessment_execution_id'];
    $s->dispatch(array('id'=>'SCOPED_FUTURE','kind'=>'NATIVE_LOGIC','data'=>array('block_execution_id'=>$id,'answers'=>array('NQ_ONE'=>4,'NQ_TWO'=>'go'),'question_states'=>array('NQ_ONE'=>'answered','NQ_TWO'=>'answered'),'changed_questions'=>array('NQ_ONE'))));$a=$s->snapshot()['logical_trajectory']['audit'][0];lc_assert($a['result']===($scoped?'UNKNOWN':'TRUE'));if($scoped){lc_assert(!$a['applied']);lc_assert($a['sources'][0]['state']['reason']==='OUTSIDE_TRACK_PAST');}$copy=E\Simulator::restore($s->compiled(),$s->checkpoint(),str_repeat('01',32));lc_assert($copy->snapshot()===$s->snapshot());}
});
