    $d=lc_fixture();$r=lc_rule();$r['reference_scope']='TRACK_PAST_V1';$d['protocol_metadata']['trajectory_conditions']=array($r);(new E\DefinitionCompiler())->compile($d);$d['protocol_metadata']['trajectory_conditions'][0]['reference_scope']='FUTURE_OK';lc_reject(function()use($d){(new E\DefinitionCompiler())->compile($d);},'INVALID_REFERENCE_SCOPE');
