lc_test('Native random question order bounds the past using the stored selection',function(){
    $d=lc_past_definition();foreach($d['nodes'] as &$n)if($n['id']==='CURRENT'){foreach($n['metadata']['native_questions'] as $i=>&$q)$q['randomization_path']=array(array('randomization_id'=>'NR_ORDER','candidate_id'=>'C_'.$i));unset($q);}unset($n);
    $r=array('source'=>array('assessment_id'=>'CURRENT','question_id'=>'NQ_TWO'),'event'=>'ANSWER');$ref=array('kind'=>'ANSWER','assessment_id'=>'CURRENT','question_id'=>'NQ_ONE');
    lc_assert(E\LogicalPast::allows($d,$r,$ref,array(),array('CURRENT|NR_ORDER'=>array('C_0','C_1','C_2'))));
    lc_assert(!E\LogicalPast::allows($d,$r,$ref,array(),array('CURRENT|NR_ORDER'=>array('C_1','C_0','C_2'))));
    lc_assert(!E\LogicalPast::allows($d,$r,$ref,array(),array('CURRENT|NR_ORDER'=>array('C_1'))));
    lc_assert(E\LogicalPast::allows($d,$r,array('kind'=>'RANDOM_RESOLVED','assessment_id'=>'CURRENT','randomization_id'=>'NR_ORDER'),array(),array('CURRENT|NR_ORDER'=>array('C_1'))));
});
