    $s->dispatch(array('id'=>'STATE_FUTURE_EVENT','kind'=>'NATIVE_LOGIC','data'=>array('block_execution_id'=>$id,'event'=>'BLOCK_STATE','state_transition'=>array('node_id'=>'E_POST','state'=>'AVAILABLE'))));$logical=$s->snapshot()['logical_trajectory'];lc_assert((empty($logical['cancelled_blocks'])&&empty($logical['cancelled_opportunities']))===$scoped);}
